using System;
using System.IO;
using System.Text;
using Furycube.G9.Macros;

internal static class MacroTests {
    static int assertions;
    static void Check(bool condition,string message){assertions++;if(!condition)throw new Exception(message);}
    static void Reject(Action action,string message){assertions++;try{action();}catch(InvalidDataException){return;}throw new Exception("Expected rejection: "+message);}
    static MacroStep Key(bool down,int vk){return new MacroStep{Kind=down?MacroStepKind.KeyDown:MacroStepKind.KeyUp,VirtualKey=vk};}
    static MacroLibrary Fixture(){return MacroProjectCodec.FromJson("{\"format\":\"FURYCUBE-G9-MACROS\",\"version\":1,\"macros\":[{\"name\":\"Комбинация\",\"repeatMode\":\"Hold\",\"repeatCount\":2,\"steps\":[{\"kind\":\"KeyDown\",\"virtualKey\":17},{\"kind\":\"KeyDown\",\"virtualKey\":65},{\"kind\":\"Delay\",\"milliseconds\":35},{\"kind\":\"KeyUp\",\"virtualKey\":65},{\"kind\":\"KeyUp\",\"virtualKey\":17},{\"kind\":\"MouseDown\",\"button\":\"Back\"},{\"kind\":\"MouseUp\",\"button\":\"Back\"},{\"kind\":\"MouseMove\",\"x\":-13,\"y\":27},{\"kind\":\"Wheel\",\"delta\":-120}]}]}");}
    static void KnownFixture(){var library=Fixture();var m=library.Macros[0];Check(m.Name=="Комбинация"&&m.RepeatMode==MacroRepeatMode.Hold&&m.RepeatCount==2,"symbolic repeat and Unicode name");Check(m.Steps.Count==9,"independently authored complete fixture");Check(m.Steps[0].VirtualKey==17&&m.Steps[1].VirtualKey==65,"Ctrl+A identity preserved");Check(m.Steps[2].DelayMilliseconds==35,"explicit35ms delay");Check(m.Steps[5].Button==MacroMouseButton.Back&&m.Steps[6].Kind==MacroStepKind.MouseUp,"mouse release identity");Check(m.Steps[7].X==-13&&m.Steps[7].Y==27&&m.Steps[8].Delta==-120,"signed movement and scroll");Check(m.GetWarnings().Length==0,"balanced modifier combination");string json=MacroProjectCodec.ToJson(library);Check(json.Contains("\"kind\":\"MouseMove\"")&&!json.Contains("VirtualKey"),"explicit portable schema, symbolic enum");Check(MacroProjectCodec.FromJson(json).Macros[0].Steps[7].X==-13,"portable roundtrip");var clone=m.Clone();clone.Steps[0].VirtualKey=18;Check(m.Steps[0].VirtualKey==17,"deep clone retains independent steps");}
    static void Schema(){string good=MacroProjectCodec.ToJson(Fixture());Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"version\":1","\"version\":2"));},"future version");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("FURYCUBE-G9-MACROS","other"));},"wrong format");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"repeatCount\":2","\"repeatCount\":1.5"));},"fractional integer");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"Hold\"","\"2\""));},"numeric enum string");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"KeyDown\"","\"keydown\""));},"enum typo");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"virtualKey\":17","\"virtualKey\":17,\"delay\":9"));},"extra incompatible step field");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"virtualKey\":17","\"virtualKey\":null"));},"null key");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"virtualKey\":17","\"virtualKey\":999999999999"));},"oversized integer");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"x\":-13,",""));},"missing movement axis");Reject(delegate{MacroProjectCodec.FromJson("null");},"null root");Reject(delegate{MacroProjectCodec.FromJson("{");},"malformed JSON");Reject(delegate{MacroProjectCodec.FromJson(good.Replace("\"macros\":[","\"macros\":{\"item\":"));},"wrong collection type");var library=Fixture();library.Macros.Add(library.Macros[0].Clone());Reject(delegate{MacroProjectCodec.ToJson(library);},"duplicate names");}
    static void Bounds(){foreach(int key in new[]{8,17,48,65,254})new MacroStep{Kind=MacroStepKind.KeyDown,VirtualKey=key}.Validate();Reject(delegate{Key(true,7).Validate();},"mouse-code collision");Reject(delegate{Key(true,255).Validate();},"invalidVK");new MacroStep{Kind=MacroStepKind.MouseMove,X=-32768,Y=32767}.Validate();Reject(delegate{new MacroStep{Kind=MacroStepKind.MouseMove,X=32768}.Validate();},"movement overflow");Reject(delegate{new MacroStep{Kind=MacroStepKind.Wheel,Delta=0}.Validate();},"zero scroll");Reject(delegate{new MacroStep{Kind=MacroStepKind.Delay,DelayMilliseconds=100000}.Validate();},"delay overflow");Reject(delegate{new MacroStep{Kind=MacroStepKind.KeyDown,VirtualKey=65,Delta=120}.Validate();},"unrelated data");var macro=new MacroDefinition{Name="test",RepeatCount=1000};Reject(macro.Validate,"repeat overflow");macro.RepeatCount=1;macro.Name=new string('a',21);Reject(macro.Validate,"name length");macro.Name="test\n";Reject(macro.Validate,"multiline name");}
    static void RecordedTiming(){var recorder=new MacroRecorder(MacroDelayMode.Recorded,10);Check(!recorder.Append(Key(false,65),20),"unpaired release excluded on capture start");Check(recorder.Append(Key(true,17),100),"modifier first press");Check(recorder.Append(Key(true,65),150),"second press");Check(!recorder.Append(Key(true,65),160),"auto-repeat keydown excluded");Check(recorder.Append(Key(false,65),215),"release");var steps=recorder.Finish();Check(steps.Count==6,"events plus two pauses plus held modifier release");Check(steps[1].DelayMilliseconds==50&&steps[3].DelayMilliseconds==65,"ignored repeat does not alter timing origin");Check(steps[5].Kind==MacroStepKind.KeyUp&&steps[5].VirtualKey==17,"stop releases held modifier in project");steps[0].VirtualKey=18;Check(recorder.Finish()[0].VirtualKey==17,"returned result is independent");var macro=new MacroDefinition{Steps=recorder.Finish()};Check(macro.GetWarnings().Length==0,"recorded result remains balanced");
        var held=new MacroRecorder(MacroDelayMode.Minimum,0);held.Append(Key(true,17),0);held.Append(Key(true,65),1);var finished=held.Finish();Check(finished[2].VirtualKey==65&&finished[3].VirtualKey==17,"stop releases held combination in reverse press order");
        var longWait=new MacroRecorder(MacroDelayMode.Recorded,0);longWait.Append(Key(true,65),0);longWait.Append(Key(false,65),200005);var result=longWait.Finish();Check(result.Count==5&&result[1].DelayMilliseconds==99999&&result[2].DelayMilliseconds==99999&&result[3].DelayMilliseconds==7,"long pause split preserves duration exactly");
        bool rejected=false;try{recorder.Append(Key(true,66),1);}catch(ArgumentOutOfRangeException){rejected=true;}Check(rejected,"time reversal rejected");
    }
    static void ModesAndLimit(){var fixedMode=new MacroRecorder(MacroDelayMode.Fixed,23);fixedMode.Append(new MacroStep{Kind=MacroStepKind.MouseDown,Button=MacroMouseButton.Forward},0);fixedMode.Append(new MacroStep{Kind=MacroStepKind.MouseUp,Button=MacroMouseButton.Forward},900);Check(fixedMode.Finish()[1].DelayMilliseconds==23,"fixed mode ignores wall interval");var minimum=new MacroRecorder(MacroDelayMode.Minimum,99);minimum.Append(Key(true,48),0);minimum.Append(Key(false,48),100);Check(minimum.Finish().Count==2,"minimum mode adds no synthetic pause");var boundary=new MacroRecorder(MacroDelayMode.Minimum,0);for(int i=0;i<2048;i++){boundary.Append(Key(true,65),i*2);boundary.Append(Key(false,65),i*2+1);}Check(boundary.Count==4096,"bounded full recording");Reject(delegate{boundary.Append(Key(true,66),5000);},"limit must reserve release");Check(boundary.Finish().Count==4096,"rejected append does not corrupt recording");var incomplete=new MacroDefinition();incomplete.Steps.Add(Key(true,65));Check(incomplete.GetWarnings().Length==1,"authoring warns about missing release");}
    static void Files(){string folder=Path.Combine(Path.GetTempPath(),"g9-macro-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{string path=Path.Combine(folder,"library.g9macros.json");MacroProjectCodec.Save(Fixture(),path);var bytes=File.ReadAllBytes(path);Check(bytes.Length>3&&!(bytes[0]==239&&bytes[1]==187&&bytes[2]==191),"JSON UTF8 without BOM");Check(!File.ReadAllText(path).Contains(folder),"project contains no private filesystem path");var library=MacroProjectCodec.Load(path);library.Macros[0].Name="Второй";MacroProjectCodec.Save(library,path);Check(MacroProjectCodec.Load(path).Macros[0].Name=="Второй","atomic replace updates existing portable file");Check(Directory.GetFiles(folder).Length==1,"temporary save files removed");}finally{Directory.Delete(folder,true);}}
    static int Main(){try{KnownFixture();Schema();Bounds();RecordedTiming();ModesAndLimit();Files();Console.WriteLine("MacroTests PASS "+assertions);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
